def rows(p):
    with p.open(newline='') as f:return list(csv.DictReader(f))
def load(p):return json.loads(p.read_text())
def table(headers,data):
    return '<table><thead><tr>'+''.join('<th>'+html.escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in data)+'</tbody></table>'
def figure(name,caption):return f'<figure><img src="FIGURES/{name}.png" alt="{html.escape(caption)}"><figcaption>{caption}</figcaption></figure>'
STYLE="""*{box-sizing:border-box}body{margin:0;background:#f2f5f4;color:#18333c;font:17px/1.65 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}main{max-width:1160px;margin:auto;padding:40px 32px 80px}header{padding:25px 0 35px}h1{font-size:48px;line-height:1.1;letter-spacing:-1px}h2{font-size:29px;line-height:1.2}h3{font-size:21px}section{background:white;padding:30px 36px;border-radius:12px;margin:22px 0;border:1px solid #dbe4e1}a{color:#006e77;text-underline-offset:3px}p{max-width:95ch}.lead{font-size:23px;color:#4a646d}.kicker{color:#007f7f;letter-spacing:.12em;font-size:12px;font-weight:700}.note{background:#e5f3ee;border-left:4px solid #008a80;padding:18px 24px;margin:20px 0}.warn{background:#fff3df;border-color:#bd7f28}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px;border-bottom:1px solid #dce5e1;text-align:left;vertical-align:top}th{background:#e8f1ee}tr:nth-child(even){background:#f8faf9}img,video{max-width:100%;height:auto;border-radius:5px}figure{margin:25px 0}figcaption,.small{color:#546c73;font-size:14px}code{font-size:.85em;background:#eaf0ed;padding:2px 5px;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#eaf0ed;padding:20px;font-size:14px}li{margin:10px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.button{display:inline-block;background:#006c73;color:white;padding:12px 18px;border-radius:7px;text-decoration:none;margin:8px 8px 8px 0}details{border:1px solid #dbe4e1;border-radius:8px;padding:16px;margin-top:18px}summary{font-weight:700;cursor:pointer}blockquote{margin:0;padding:20px;border-left:4px solid #008a80;background:#edf5f1}@media(max-width:700px){main{padding:20px 12px}section{padding:22px 18px}h1{font-size:35px}table{display:block;overflow-x:auto}}@media print{body{background:white;font-size:11px}main{padding:0}section{border:0;padding:8px 0}h1{font-size:30px}h2{font-size:22px}figure{break-inside:avoid}video{display:none}.button{background:none;color:black}}"""
