fig.suptitle('Test externe figé : les résultats dépendent fortement de la source',fontsize=17,y=.97)
fig.text(.05,.025,'58 vues frontales ; moyenne des erreurs par image. Les 38 vues latérales sont rapportées séparément.\nRéférence : milieu des bords extérieurs publics ; ce n’est pas une erreur physique en mètres.',fontsize=10);fig.subplots_adjust(left=.075,right=.98,bottom=.25,top=.78,wspace=.32);save(fig,'01_test_externe')
stress=load(O/'02_RECADRAGES_ET_ROBUSTESSE/RESUME.json');order=['original','vga_640x480','crop_10pct_each_edge','dark_55pct','blur_sigma4px'];d={x['variant']:x for x in stress};lab=['Image originale','VGA 640 × 480','Recadrage 10 %','Luminosité 55 %','Flou σ = 4 px']
fig,ax=plt.subplots(figsize=(11,5));x=np.arange(5);ax.bar(x-.18,[d[k]['baseline_same_domain_mae_px'] for k in order],.36,label='Original, même zone évaluée',color='#bacdcc');ax.bar(x+.18,[d[k]['image_macro_mae_px'] for k in order],.36,label='Après transformation',color='#0c8587');ax.set_xticks(x,lab);ax.set_ylabel('Erreur moyenne de l’axe (pixels natifs)');ax.set_title('Recadrer teste la robustesse ; cela ne crée pas une nouvelle capture',pad=18);ax.legend(frameon=False);ax.set_ylim(0,6.5);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
for i,k in enumerate(order):ax.text(i+.18,d[k]['image_macro_mae_px']+.08,f"{d[k]['image_macro_mae_px']:.2f}",ha='center',fontsize=10)
fig.text(.08,.025,'12 images de développement déjà utilisées pour choisir le modèle. Pour le recadrage, seule la zone conservée est évaluée.\nLa couverture varie légèrement ; ces différences ne prouvent pas un gain sur une nouvelle vidéo.',fontsize=10);fig.subplots_adjust(left=.09,right=.98,bottom=.23,top=.85);save(fig,'02_robustesse')
errs=rows(O/'03_PREMIERS_METRES/ERREURS_METRES_PAR_IMAGE.csv');fig,ax=plt.subplots(figsize=(12,5));x=np.arange(len(errs));ax.bar(x-.18,[100*float(r['mae_equiv_m_g1067']) for r in errs],.36,label='Hypothèse 1,067 m',color='#0c8587');ax.bar(x+.18,[100*float(r['mae_equiv_m_g1435']) for r in errs],.36,label='Hypothèse 1,435 m',color='#d08a35');ax.set_xticks(x,[r['frame_index'] for r in errs],rotation=45);ax.set_xlabel('Indice de frame normalisé — TSV 03676');ax.set_ylabel('Écart équivalent à l’annotation (cm)');ax.set_title('Une erreur en centimètres conditionnée par l’écartement supposé',pad=18);ax.legend(frameon=False);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True);fig.text(.08,.025,'Échelle locale = écartement supposé / largeur ANNOTÉE. 1 139 sections ; 90 sections trop étroites exclues.\nCes écarts aux annotations de développement ne valident pas une précision physique.',fontsize=10);fig.subplots_adjust(left=.08,right=.98,bottom=.30,top=.85);save(fig,'03_erreur_metres_conditionnelle')
fr=rows(V/'02_TSV_03676_180S/FRAMES_VITESSE_VECTEUR.csv');a=[r for r in fr if r['travel_segment_distance_m_estimate']];fig,ax=plt.subplots(figsize=(10,4.5));ax.plot([float(r['real_elapsed_s']) for r in a],[float(r['travel_segment_distance_m_estimate']) for r in a],color='#0c8587');ax.set_xlabel('Temps physique estimé depuis le début (s)');ax.set_ylabel('Avancement estimé (m)');ax.set_title('TSV 03676 : environ 1 397 m sur 179 s couverts');ax.grid(alpha=.2);fig.text(.09,.025,'Vitesses moyennes issues de 19 positions GPS affichées dans la vidéo, par intervalles de 9 à 11 s.\nIncertitude instrumentale inconnue ; les 28 dernières frames n’ont pas de vitesse.',fontsize=10);fig.subplots_adjust(left=.09,right=.98,bottom=.26,top=.86);save(fig,'04_avancement')
bands=[];raw=rows(V/'ERREURS_SUR_FRAMES_REFERENCE.csv');equiv={(r['frame_index'],r['y_px']):r for r in rows(V/'ERREURS_EQUIVALENTES_METRES.csv')}
for lo,hi in [(0,.25),(.25,.5),(.5,.75),(.75,1)]:
    a=[r for r in raw if lo<=int(r['y_px'])/1080<hi];e=np.array([float(r['error_selected_px']) for r in a]);m=[float(equiv[r['frame_index'],r['y_px']]['error_equivalent_m_g1067']) for r in a if equiv[r['frame_index'],r['y_px']]['error_equivalent_m_g1067']]
    if len(e):bands.append(dict(video_id='TSV_03676',y_fraction_start=lo,y_fraction_end=hi,reference_images=len({r['frame_index'] for r in a}),reference_sections=len(e),bias_px=float(e.mean()),mae_px=float(np.abs(e).mean()),rmse_px=float(np.sqrt(np.square(e).mean())),p95_abs_error_px=float(np.percentile(np.abs(e),95)),conditional_mae_m_g1067=float(np.abs(m).mean()) if m else None,scope='Descriptive development residuals; correlated sections; not known error for unseen frames or calibrated uncertainty'))
with (V/'ERREUR_DEVELOPPEMENT_PAR_HAUTEUR.csv').open('w',newline='') as f:
    wr=csv.DictWriter(f,fieldnames=list(bands[0]));wr.writeheader();wr.writerows(bands)
for name in ['PROTOCOLE_FIGE.json','IMAGES_TEST_FIGEES.csv','CORRECTION_METADATA_SOURCE.json']:shutil.copy2(RUN/name,O/name)
body="""<header><p class="kicker">TSV · Bilan de la version figée · 18 octobre 2026</p><h1>Un test externe terminé.<br>Un premier passage aux mètres.</h1><p class="lead">L’axe, ses limites, le temps, la vitesse et les premières valeurs métriques sont livrés. Le test montre précisément où cette version reste insuffisante.</p><a class="button" href="../GABARIT_V3_METRES_ESTIMES_20261018/LIRE_MOI.html">Paquet gabarit V3</a><a class="button" href="../../02_A_PARTAGER/GABARIT_V3_METRES_ESTIMES_20261018.zip">ZIP à transmettre</a></header>
<section><h2>Ce qui a réellement changé</h2><ol><li><strong>Un contrôle externe :</strong> 96 nouvelles images publiques, six séquences sources, modèle et sélection figés avant l’inférence. Deux nouveaux extraits de 50 frames ont aussi été traités.</li><li><strong>Des mètres avec leur statut :</strong> avancement à partir de la vitesse et du temps physique, échelle latérale approximative à partir d’un écartement supposé.</li><li><strong>Des erreurs explicables :</strong> écarts en pixels aux références, conversion conditionnelle en centimètres, couverture et échecs séparés.</li><li><strong>Un paquet clair :</strong> deux vidéos TSV, CSV par frame et par point, exemples identiques pour l’autre équipe et règles de fusion.</li></ol><p>Le réseau n’a pas été réentraîné pendant ce test. La V3 conserve les prédictions retenues en V2 ; les ajouts concernent les mètres, les contrôles et l’explication. Aucun nouveau gain d’apprentissage n’est revendiqué.</p></section>
<section><h2>Le nouveau test : ce qu’il démontre</h2><p>Les 96 images proviennent de GAF, OSDaR26_GAF et S4R, publiées dans RAIL-BENCH. Les vidéos TSV locales avaient déjà servi au développement. Ce test public est nouveau pour notre modèle figé ; il reste différent d’un test de terrain TSV.</p><p><a href="https://www.mrt.kit.edu/railbench/track_detection">Source officielle : RAIL-BENCH</a> · <a href="https://arxiv.org/abs/2604.22507">Article et provenance des données</a></p>"""
body+=table(['Ensemble','Images','Sans aucun axe','Couverture des sections évaluables','Erreur moyenne'],[['Frontales (center/middle)',58,0,'94,22 %','1,791 % de largeur ; 47 images avec erreur calculable'],['Latérales (left/right)',38,37,'0 %','Non calculable sur les références retenues'],['Total figé',96,37,'77,48 %','Les absences ne valent pas zéro']])
body+='<div class="note warn"><strong>Un axe présent n’est pas nécessairement juste.</strong> Sur 58 images frontales, 48 ont une paire de référence exploitable ; 47 ont une prédiction à des hauteurs comparables. La moyenne des erreurs ne porte que sur ces 47 images. Les sections manquantes sont comptées séparément.</div>'
body+=figure('01_test_externe','La série S4R est nettement plus difficile. Une faible erreur sur une source ne compense pas les pertes ou les déviations sur une autre.')
body+="""<p>La séparation frontales/latérales a été faite <strong>après le test</strong>, pour l’interpréter à partir des noms de caméras des auteurs. Les 96 résultats initiaux sont conservés ; aucun modèle ou seuil n’a été adapté à ces résultats.</p><p>La référence publique suit les <strong>bords extérieurs</strong> des têtes de rail. Nous évaluons leur milieu uniquement quand exactement deux rails non occultés forment une paire non ambiguë dans une ligne de pixels. Ce n’est pas exactement la cible des bords intérieurs TSV. Les aiguillages à plusieurs paires possibles ne reçoivent donc pas artificiellement un score de « bonne branche ».</p>
<details><summary>Protocole et limites scientifiques</summary><ul><li>Aucun doublon de fichier identique détecté avec les 3 130 fichiers distincts des trois manifestes d’apprentissage. Un SHA256 ne détecte pas tous les réencodages et ne démontre pas l’indépendance de tout trajet ou du préentraînement générique.</li><li>Six séquences ne signifient pas six expériences indépendantes. Les sections voisines sont corrélées ; aucune certitude statistique artificielle n’est calculée.</li><li>Onze images non annotées avaient hauteur et largeur inversées dans un en-tête public. Les pixels et le tableau source concordent ; elles restent évaluées visuellement, sans annotation inventée.</li><li>Le split public de validation RAIL-BENCH sert ici de test externe nouveau pour notre modèle. Ce n’est ni le score du challenge caché, ni une certification TSV.</li></ul><p><a href="PROTOCOLE_FIGE.json">Protocole figé</a> · <a href="IMAGES_TEST_FIGEES.csv">Liste complète</a> · <a href="01_TEST_EXTERNE_FIGE/RESULTATS_PAR_IMAGE.csv">Résultats par image</a> · <a href="AUDIT_EXPORTS_ET_SOURCES.json">Audit</a></p></details></section>
<section><h2>Voir les réussites et les limites</h2><div class="grid">"""
for iid,txt in [(1501,'Vue frontale GAF : bon alignement visible.'),(1977,'S4R : déviation près du bas de l’image.'),(1989,'Courbe S4R : axe plausible en haut, dégradation en bas.'),(1920,'Caméra latérale : aucun axe, cadrage différent de celui appris.')]:
    body+=f'<figure><a href="01_TEST_EXTERNE_FIGE/apercus/{iid}.jpg"><img src="01_TEST_EXTERNE_FIGE/apercus/{iid}.jpg" alt="{txt}"></a><figcaption>{iid} — {txt} Vert : prédiction ; rose : référence.</figcaption></figure>'
body+='</div><p>Exemples issus de la première image ou de l’image médiane des groupes inspectés. Les 96 aperçus sont conservés dans <code>01_TEST_EXTERNE_FIGE/apercus</code>. Ils illustrent les mesures complètes sans les remplacer.</p></section>'
body+='<section><h2>Deux nouvelles vidéos avec une référence de déplacement</h2><p>Les premières 50 frames de deux séquences publiques ont été traitées sans modification du modèle. Lecture à moitié vitesse : environ 4,9 secondes physiques sont montrées en 10 secondes.</p><div class="grid">'
for s in load(O/'04_NOUVELLES_SEQUENCES/RESUME.json'):
    folder='04_NOUVELLES_SEQUENCES/'+s['scene'];body+=f'<article><h3>{s["scene"]}</h3><video controls preload="metadata" poster="{folder}/apercu_025.jpg" src="{folder}/DETECTION_RALENTIE_0_5X.mp4"></video><p>50 frames ; axe présent sur les 50. Déplacement de référence fourni : <strong>{s["reference_travel_m"]:.1f} m</strong>.</p><a href="{folder}/FRAMES_AXE_ET_POSE_REFERENCE.csv">CSV avec position de référence</a> · <a href="{folder}/AXE_POINTS.csv">Points de notre axe</a></article>'
body+='''</div><div class="note warn">Les positions en mètres et la calibration sont fournies par le jeu public : <strong>elles ne sont pas estimées par notre détecteur</strong>. L’axe de ces clips n’a pas d’annotation de référence dans cet export ; son erreur reste inconnue. Le nom « train » est celui du split du benchmark ; notre modèle n’a pas été entraîné dessus.</div><p><a href="https://www.mrt.kit.edu/railbench/ego_motion_estimation">Source officielle des poses et de la calibration</a>. Images et clips publics restent locaux et ne sont pas inclus dans le ZIP gabarit : consulter les conditions avant redistribution.</p></section>
<section><h2>Recadrer une ancienne vidéo : utile, mais pas nouveau</h2><p>Un recadrage garde la même scène, les mêmes traverses et le même instant. Il peut améliorer la visibilité pour le réseau ou tester sa robustesse. Il ne transforme pas une ancienne vidéo en test indépendant.</p>'''
body+=figure('02_robustesse','Le réseau reçoit déjà une image 640 × 480 avec conservation des proportions. Le passage VGA change donc peu le résultat. Le flou et l’assombrissement augmentent l’erreur.')
body+='<p>Le recadrage de 10 % de chaque bord donne <strong>3,37 px</strong> contre <strong>3,79 px</strong> pour l’original sur la même zone restante, soit environ <strong>10,9 % de moins</strong> dans cet essai de développement. On ne retire pas les zones difficiles du test externe pour annoncer un meilleur score.</p></section>'
body+='''<section><h2>Comment les premières données en mètres sont obtenues</h2><h3>1. L’avancement du train le long du trajet</h3><p>On multiplie la vitesse par la durée physique entre deux frames, puis on additionne ces déplacements. TSV_record utilise sa télémétrie ; TSV 03676 utilise des vitesses moyennes estimées entre 19 positions GPS lisibles dans la vidéo.</p><pre>déplacement d’un intervalle ≈ vitesse × durée physique
avancement = somme des déplacements disponibles</pre>'''
body+=figure('04_avancement','L’avancement place les observations successives le long du trajet. Il ne donne pas à lui seul la distance entre la caméra et chaque point du rail.')
body+='''<p>Pour <strong>TSV_record</strong>, les portions retenues totalisent environ <strong>253,0 km sur 13 199,6 s physiques</strong>, en <strong>189 segments</strong>. C’est la somme des portions connues, pas une trajectoire complète reconstruite. Après un trou, la distance du nouveau segment repart de zéro.</p><h3>2. Une échelle latérale approximative</h3><p>À une hauteur donnée dans l’image, si l’écartement supposé vaut G et que le couloir fait w pixels, G/w donne une première échelle locale.</p><pre>échelle supposée = G / largeur du couloir en pixels
écart latéral approximatif = (x_axe − milieu horizontal de l’image) × échelle</pre>'''
body+=table(['Vidéo','Hypothèse','Base et statut'],[['TSV 03676','1,067 m','Hypothèse plausible de voie historique nigériane, d’après le GPS visible et la <a href="https://nrc.gov.ng/">NRC</a>. Ligne exacte non confirmée.'],['TSV_record','1,435 m','Hypothèse de voie normale belge, cohérente avec le GPS et la <a href="https://infrabel.be/sites/default/files/wysiwyg-files/rgdg06_partie_iv_titre_i_chapitre_i.pdf">référence Infrabel</a>. Voie précise à confirmer.']])
body+='''<div class="note warn">L’écartement est une <strong>référence supposée</strong>, pas une mesure du modèle. Imposer 1,067 m pour définir l’échelle ne permet pas d’annoncer avoir mesuré exactement 1,067 m. Une ligne de pixels n’est pas forcément perpendiculaire aux rails : virage, dévers et inclinaison de caméra modifient la géométrie. L’offset est relatif au milieu horizontal de l’image, pas un X 3D calibré.</div><p>La conversion est rejetée si le couloir fait moins de 2 % de la largeur d’image. La profondeur Z, l’écartement réel et l’incertitude physique restent vides. VGA ne définit aucune distance réelle.</p></section>
<section><h2>Une erreur chiffrée, avec sa signification exacte</h2><p>Sur les 12 références de développement TSV, la MAE de l’axe est <strong>3,82 pixels natifs</strong>, en faisant d’abord la moyenne par image. Pour convertir les erreurs, on utilise la <strong>largeur annotée par l’humain</strong>, afin de ne pas masquer une erreur de largeur prédite.</p><pre>erreur équivalente (m) = erreur axe (px) × G / largeur ANNOTÉE (px)</pre>'''
body+=figure('03_erreur_metres_conditionnelle','Passer de 1,067 à 1,435 m augmente les conversions de 34,5 %. Les prédictions en pixels sont identiques.')
body+=table(['Mesure','Valeur','Interprétation'],[['Moyenne par image, G = 1,067 m','2,48 cm','Écart équivalent aux annotations de développement.'],['Moyenne par image, G = 1,435 m','3,34 cm','Même prédiction, autre hypothèse d’échelle.'],['95e percentile absolu, G = 1,067 m','6,49 cm','95 % des sections convertibles observées sont sous ce seuil ; pas un intervalle de confiance ni une garantie future.'],['Sections convertibles','1 139 / 1 229','90 trop étroites exclues ; sections corrélées.'],['Erreur physique réelle d’une frame non annotée','Inconnue','La confiance du réseau ne remplace pas une référence.']])
body+='''<p><strong>Exemple de calcul :</strong> 200 pixels de largeur, G = 1,067 m et 4 pixels d’erreur donnent 4 × 1,067 / 200 = 0,02134 m, soit 2,13 cm. C’est un exemple pédagogique, pas une mesure supplémentaire.</p><p><a href="03_PREMIERS_METRES/ERREURS_METRES_PAR_IMAGE.csv">Erreurs par image</a> · <a href="../GABARIT_V3_METRES_ESTIMES_20261018/ERREUR_DEVELOPPEMENT_PAR_HAUTEUR.csv">Biais, MAE, RMSE et percentile par hauteur</a></p></section>
<section><h2>La suite concrète pour améliorer le système</h2><ol><li><strong>Conserver ce test tel quel.</strong> Si nous adaptons le modèle aux échecs vus ici, ces images deviennent du développement. La version suivante devra être testée sur d’autres captures réservées.</li><li><strong>Diversifier les caméras frontales.</strong> Varier position de l’horizon, champ de vision, éclairage et proportions ; contrôler les zones proches qui se dégradent. Ne pas réentraîner sur les prédictions erronées sans les relire.</li><li><strong>Garder du public pendant l’adaptation TSV.</strong> Les essais précédents à trois graines suggèrent un compromis pour préserver la diversité, pas un gain universel. Comparer les candidats à budget comparable sur un développement séparé.</li><li><strong>Évaluer la bonne branche aux aiguillages.</strong> Repérer la voie réellement empruntée sur quelques séquences continues, compter changements de branche, pertes et reprises. Un masque plausible ne suffit pas.</li><li><strong>Lisser avec contrôle du retard.</strong> Suivi causal des deux bords, rejet des sauts et reset après interruption ; mesurer erreur, couverture et délai en courbe. La V3 conserve l’axe brut retenu : le lissage historique augmentait l’erreur sur nos références.</li><li><strong>Valider les mètres.</strong> Confirmer l’écartement, obtenir une calibration de caméra et des distances de contrôle indépendantes. Une homographie suppose une surface localement plane ; pentes et dévers demandent davantage de géométrie.</li></ol><div class="note"><strong>État du travail :</strong> test externe de la version actuelle terminé, paquet gabarit et premiers mètres livrés. La validation physique de terrain reste ouverte : les références correspondantes n’existent pas encore pour vos vidéos.</div></section>
<section><h2>Vocabulaire pour présenter</h2>'''
body+=table(['Terme','Définition'],[['Axe médian','Milieu des deux limites à chaque hauteur dans l’image ; pas automatiquement un axe 3D.'],['MAE','Moyenne de la taille des erreurs, sans signe.'],['Biais','Moyenne signée ; positive = décalage à droite.'],['RMSE','Racine de la moyenne des erreurs au carré ; les grandes erreurs pèsent davantage.'],['Couverture','Part des sections de référence avec un axe comparable.'],['Incertitude','Doute sur une mesure, à estimer par une méthode et des références ; un percentile n’est pas automatiquement une incertitude calibrée.'],['Pose','Position et orientation dans un repère 3D.'],['Test externe figé','Évaluation sur de nouvelles données sans ajuster la version déjà choisie à leurs résultats.']])
body+='''<blockquote>« Nous détectons le couloir et son axe dans l’image. Les deux exports donnent les vecteurs, la vitesse et l’avancement disponibles. Le test figé sur 96 images externes montre un effet important de la caméra et de la source. Les premiers mètres utilisent la télémétrie ou une échelle latérale supposée. Les 2,48 cm sont une conversion conditionnelle d’erreurs aux annotations, pas une précision physique certifiée. »</blockquote></section>'''
(O/'LIRE_LES_RESULTATS.html').write_text(page('TSV — tests externes et premiers mètres',body))
guide='''<header><p class="kicker">Équipe rails → équipe gabarit · V3 · 18 octobre 2026</p><h1>Deux vidéos. Leurs axes.<br>La vitesse et les premiers mètres.</h1><p class="lead">Une seule sortie retenue de notre équipe, à comparer avec celle de l’autre équipe sur exactement les mêmes images.</p></header><section><h2>Commencer par un petit exemple</h2><ol><li>Ouvrir la frame 1375 dans <strong>02_TSV_03676_180S/IMAGES_COMMUNES</strong>.</li><li>Lire ses points dans <strong>EXEMPLE_SEQUENCE_POINTS.csv</strong>, puis son temps et sa vitesse dans <strong>EXEMPLE_SEQUENCE_FRAMES.csv</strong>.</li><li>Joindre avec <code>video_id + frame_index + y_px</code>. Si les hauteurs diffèrent, interpoler seulement dans un même segment continu.</li><li>Passer aux CSV complets et vérifier visuellement avec les MP4.</li></ol>'''
guide+=table(['Vidéo','Découpage','Vitesse'],[['TSV_record','7 608 frames ; 5 images/s ; 1 521,6 s de lecture ; 1280 × 720','Télémétrie ; temps physique différent du temps de lecture.'],['TSV 03676','5 399 frames normalisées ; 30 images/s ; 179,967 s ; 1920 × 1080','Moyenne GPS estimée sur 9 à 11 s ; environ 1 397 m sur 179 s couverts.']])
guide+='</section><section><h2>Les fichiers à utiliser</h2>'
guide+=table(['Fichier','Contenu'],[['FRAMES_VITESSE_VECTEUR.csv','Une ligne par frame : temps, vitesse, vecteur de l’axe segmenté, statuts et avancement estimé.'],['AXE_MEDIAN.csv','Une ligne par point : axe et limites en pixels, erreurs connues, échelle latérale supposée. Une ligne vide conserve les frames sans axe.'],['EXEMPLE_SEQUENCE_*.csv','Petits extraits avec le même schéma.'],['IMAGES_COMMUNES','Images originales identiques à fournir à l’autre équipe. Les vidéos annotées servent seulement à regarder.'],['SOURCE_ET_DECOUPAGE.json','Source, résolution, cadence, filtre et empreintes des images.'],['VIDEO_ANNOTEE.mp4','Axe, limites, vitesse, avancement et échelle estimée affichés.'],['ERREURS_SUR_FRAMES_REFERENCE.csv','Écarts aux annotations des 12 frames TSV 03676 uniquement.'],['ERREUR_DEVELOPPEMENT_PAR_HAUTEUR.csv','Biais, MAE, RMSE et percentile descriptifs ; pas erreur connue des futures frames.'],['ERREURS_EQUIVALENTES_METRES.csv','Conversion conditionnelle des résidus selon deux écartements.'],['outils','Lecture d’une frame et extraction des mêmes images depuis les vidéos originales.']])
guide+='<div class="grid">'
for folder,title in [('01_TSV_RECORD','TSV_record'),('02_TSV_03676_180S','TSV 03676')]:
    guide+=f'<article><h3>{title}</h3><video controls preload="metadata" src="{folder}/VIDEO_ANNOTEE.mp4"></video><p><a href="{folder}/EXEMPLE_SEQUENCE_FRAMES.csv">Exemple frames</a> · <a href="{folder}/EXEMPLE_SEQUENCE_POINTS.csv">Exemple points</a> · <a href="{folder}/SOURCE_ET_DECOUPAGE.json">Découpage</a></p></article>'
guide+='''</div></section><section><h2>Comment découper exactement comme nous</h2><p>Repère de l’image originale entière : origine en haut à gauche, x vers la droite, y vers le bas. Numérotation à partir de zéro. Points tous les 8 pixels verticalement, regroupés par segment ; ne pas relier deux segments séparés.</p><pre>TSV_record : fps=fps=5:start_time=0:round=near
TSV 03676 : fps=fps=30:start_time=0:round=near</pre><p>Utiliser les PNG communs et leur empreinte RGB évite les décalages. L’AVI 03676 contient 5 305 images décodées ; la normalisation en donne 5 399, dont 94 répétitions signalées. Ancienne frame 1350 = frame normalisée 1375. Les répétitions ne sont pas de nouvelles observations.</p><p>TSV_record contient des bandes noires : notre réseau utilise <code>x=370:910, y=0:720</code>, puis remet les points dans le repère complet 1280 × 720. L’autre équipe peut traiter différemment mais doit rendre ce même repère. L’entrée réseau 640 × 480 conserve les proportions et ne définit pas d’échelle physique.</p></section><section><h2>Les colonnes en mètres</h2>'''
guide+=table(['Champ','Sens et précaution'],[['train_speed_m_s / train_speed_km_h','Lire aussi speed_status, speed_is_estimated et telemetry_flags. Pour 03676 : moyenne d’intervalle GPS, pas mesure instantanée.'],['real_elapsed_s','Horloge physique. Ne pas intégrer avec video_time_s pour TSV_record, dont la lecture est accélérée.'],['travel_segment_id','Portion de télémétrie continue ; change après interruption.'],['travel_segment_distance_m_estimate','Avancement estimé depuis le début de cette portion.'],['travel_from_video_start_m_estimate','Disponible seulement tant qu’aucun trou n’a été rencontré depuis le début.'],['travel_cumulative_valid_parts_m_estimate','Somme des portions connues, pas distance complète du trajet.'],['assumed_gauge_m / scale_m_per_px_assumed','Écartement supposé / largeur prédite. Hypothèses à confirmer : 1,435 m pour TSV_record ; 1,067 m pour 03676.'],['axis_offset_from_image_midline_m_assumed','Décalage latéral local par rapport au milieu horizontal de l’image, positif à droite. Pas X 3D calibré.'],['axis_offset_m_scenario_1067 / axis_offset_m_scenario_1435','Sensibilité à deux hypothèses d’écartement.'],['error_signed_px / reference_error_equiv_m_assumed','Erreur face à une annotation de la même frame ; vide ailleurs. Conversion avec largeur humaine.'],['ground_x_m / ground_z_m / measured_gauge_m / physical_uncertainty_m','Vides : non validés. Ne jamais remplacer les inconnues par zéro.']])
guide+='''<div class="note warn"><strong>Avancement du train ≠ profondeur d’un point du rail.</strong> La vitesse avance les observations dans le trajet ; elle ne donne pas la distance caméra-point et ne suffit pas à reconstruire correctement la trajectoire 3D en virage. Il manque géométrie de caméra et orientation/pose. Les valeurs latérales sont des approximations explicites.</div></section><section><h2>Quelle erreur avons-nous ?</h2><p>Sur 12 images de développement 03676 : <strong>3,82 px</strong> de MAE moyenne par image. La conversion locale donne <strong>2,48 cm</strong> avec 1,067 m, ou <strong>3,34 cm</strong> avec 1,435 m. Ce sont des écarts équivalents aux annotations, pas une précision physique vérifiée.</p><p>Les erreurs des autres frames restent inconnues. Les statuts « ok » indiquent une cohérence interne, pas une annotation correcte ni la bonne branche à un aiguillage. Le tableau par hauteur aide à étudier les erreurs, mais ne fournit pas de poids de fusion statistiquement calibrés pour une autre caméra.</p><p>Vide = inconnu. Zéro = effectivement zéro.</p></section><section><h2>À confirmer ensemble</h2><ol><li>Une même frame et les mêmes pixels pour les deux équipes.</li><li>Horloge physique, statuts et trous de télémétrie.</li><li>Écartement réel et repère 3D.</li><li>Quelques distances de contrôle indépendantes pour valider la rectification.</li></ol><p>Les nouvelles données publiques restent hors de ce ZIP. Le paquet concerne uniquement les deux vidéos TSV indiquées.</p></section>'''
(V/'LIRE_MOI.html').write_text(page('Gabarit V3 — axes, vitesse et mètres estimés',guide))
message="""Bonjour, voici notre paquet V3 pour TSV_record et TSV 03676 (environ 180 secondes).

Il contient une seule sortie retenue de notre équipe : axe médian et deux limites, numéro de frame et temps. Vous pouvez comparer à l’autre équipe sur exactement les mêmes images.

Nous avons ajouté la vitesse disponible, l’avancement par temps physique et une première échelle latérale en mètres. Hypothèses à confirmer : 1,435 m pour TSV_record et 1,067 m pour 03676. Ce n’est pas encore une profondeur 3D calibrée.

Pour 03676, la vitesse est une moyenne estimée entre positions GPS affichées (~10 s), pas une mesure instantanée. Les trous restent signalés. Pour TSV_record, utiliser le temps physique du CSV, pas simplement le temps de lecture.

Commencez par EXEMPLE_SEQUENCE_*.csv et les PNG de IMAGES_COMMUNES. Joindre par video_id + frame_index + y_px. Les erreurs connues concernent seulement les 12 frames annotées de 03676 ; les autres restent vides, pas zéro.

LIRE_MOI.html explique les fichiers et le découpage exact. Les MP4 servent à vérifier. Aucun changement du modèle n’est revendiqué dans cette V3 : les exports, les mètres et les tests ont été complétés.
"""
